use vstd::prelude::*;

verus! {
    // Specification function: returns true if all elements of vector v are 1
    spec fn all_ones(v: &Vec<i32>) -> bool {
        forall(|i: int| (0 <= i && i < v.len() as int) ==> v.index(i as usize) == 1)
    }

    fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
        ensures result.len() == a.len()
        ensures all_ones(&result)
    {
        let n = a.len();
        let mut res = Vec::<i32>::new();
        // Initially, res is empty
        // We will push 1 onto res n times

        let mut i: usize = 0;
        while i < n
            invariant {
                i <= n,
                res.len() == i,
                all_ones(&res),
            }
            decreases n - i
        {
            res.push(1);
            i = i + 1;
        }

        res
    }
}
